<div class="card"><div class="card-header"><h3 class="card-title">Documentos liberados pela inspeção</h3></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Documento</th><th>Fornecedor</th><th>Valor</th><th>Programado</th><th>Saldo</th><th>Situação</th></tr></thead><tbody><?php foreach($itens as $i):?><tr><td><a href="/documentos/<?=e($i['documento_id'])?>"><strong><?=e($i['tipo_documento'])?> <?=e($i['documento_numero'])?></strong></a></td><td><?=e($i['fornecedor'])?></td><td><?=money($i['valor_bruto'])?></td><td><?=money($i['valor_programado'])?></td><td><?=money($i['saldo_programar'])?></td><td><span class="badge <?=round((float)$i['saldo_programar'],2)===0.0?'text-bg-success':'text-bg-warning'?>"><?=round((float)$i['saldo_programar'],2)===0.0?'Fechado':'A programar'?></span></td></tr><?php endforeach;?><?php if(!$itens):?><tr><td colspan="6" class="text-center text-body-secondary py-4">Nenhum documento liberado para programação.</td></tr><?php endif;?></tbody></table></div></div>